#!/usr/bin/env julia
#       $Id$
#  D. Sandwell 1/12/07
#  M. Wei 1/31/08
#
# alias rm 'rm -f'
# unset noclobber

function main(argv::Vector{String})
    local V::Vector{String}
    if isfile(joinpath(homedir(), ".quiet"))
        V = String[]
    else
        V = ["-V"]
    end

    #
    #
    #  project a grd file from lon/lat coordinates into range/azimuth coordinates
    #  this version only works with GMT V4.0 and higher
    #
    #  Input:
    #  trans.dat    - file generated by llt_grid2rat  (r a topo lon lat)
    #  phase_ll.grd - a GRD file of phase or anything in longitude/latitude coordinates
    #
    #  Output:
    #  phase_ra.grd - a GRD file of phase in radar coordinates
    #
    # check for number of arguments
    #
    if length(argv) < 3
        println(" ")
        println("Usage: proj_ll2ra.csh trans.dat phase_ll.grd phase_ra.grd [-I32/64]")
        println(" ")
        println("        trans.dat    - file generated by llt_grid2rat  (r a topo lon lat)")
        println("        phase_ll.grd - a GRD file of phase or anything in lon/lat-coordinates")
        println("        phase_ra.grd - output a GRD file in radar coordinates")
        println("        [-I32/64 - set the output sampling size, i.e., range/azimuth pixel number]")
        println(" ")
        exit(1)
    end

    II = "-I32/64"
    if length(argv) == 4
        II = argv[4]
    end

    #
    #  extract the phase in the r a positions
    #
    run(`gmt set FORMAT_GEO_OUT D`)
    run(pipeline(`gmt grd2xyz $(argv[2]) -s -bo3f -fg`, stdout="llp"))
    #
    #   make grids of longitude and latitude versus range and azimuth
    #
    run(pipeline(`gmt gmtconvert $(argv[1]) -o3,4,0 -bi5d -bo3f`, stdout="llr"))
    run(pipeline(`gmt gmtconvert $(argv[1]) -o3,4,1 -bi5d -bo3f`, stdout="lla"))
    #
    ginfo1 = strip(read(`gmt gmtinfo llp -I0.08333333333 -bi3f`, String))
    run(`gmt surface llr $ginfo1 -bi3f -I.00083333333333 -T.50 -Gllr.grd $V`)
    ginfo2 = strip(read(`gmt gmtinfo llp -I0.08333333333 -bi3f`, String))
    run(`gmt surface lla $ginfo2 -bi3f -I.00083333333333 -T.50 -Glla.grd $V`)
    #
    run(pipeline(`gmt grdtrack llp -nl -Gllr.grd -bi3f -bo4f`, stdout="llpr"))
    run(pipeline(`gmt grdtrack llpr -nl -Glla.grd -bi4f -bo5f`, stdout="llpra"))
    #
    # get the range, azimuth, phase columns and grid
    #
    run(pipeline(`gmt gmtconvert llpra -bi5f -bo3f -o3,4,2`, stdout="rap"))
    #
    #
    rapinfo = strip(read(`gmt gmtinfo rap -I32/64 -bi3f`, String))
    run(`gmt xyz2grd rap $rapinfo $II -r -G$(argv[3]) -bi3f`)
    #
    # clean
    #
    for f in readdir(".")
        if startswith(f, "ll")
            rm(f; force=true)
        end
    end
    rm("rap"; force=true)
end

main(ARGS)
